"""Short listening turns and observable conversational follow-through."""
def author(E,C,O,S,D):
 E('plan-G1-oral-02','S2','색연필을 쓰고 싶은 친구',[
 ('소라','색연필을 쓰고 싶어. 나는 파란색이 필요해.'),('민준','나는 노란색을 다 쓰면 상자에 넣을게.')],
 '여러분은 색연필 상자를 돌보는 친구예요. 두 친구의 말을 끝까지 듣고 소라에게 필요한 색을 확인하는 질문을 하세요. 상대가 대답할 차례를 기다렸다가 다시 확인하세요.',
 '응, 파란색 한 자루면 돼.',
 '이미 들은 색을 확인하는 대화다. 새로운 정보를 찾아야만 좋은 질문이라고 하지 않는다. 실제 질문·기다림·답 확인을 관찰하며 한 자루는 첫 질문 뒤 상대 답에서 새로 제공한다.',[
 S('소라에게 필요한 색을 확인하는 질문을 직접 하세요. 대답을 기다린 뒤 알게 된 것을 다시 말해 보세요.','예:소라야, 파란색이 필요하니? 답을 들은 뒤 파란색 한 자루면 되는구나라고 확인한다.','나는 파란색이 필요해.',[D('상대와 질문','소라에게 파란색이 필요한지 묻는다.','색을 말하지만 누구에게 묻는지 흐리다.','소라에게 노란색이 필요하다고 정한다.'),D('말차례','질문 뒤 상대가 말할 기회를 주고 답을 듣는다.','잠깐 기다리지만 상대가 말하는 중 자기 말을 이어 간다.','상대에게 답할 기회를 주지 않는다.'),D('들은 답 확인','상대 답의 파란색·한 자루를 말이나 가리키기로 확인한다.','색 또는 수량 하나만 확인한다.','상대 답과 다른 색·수량을 확정한다.')]),
 C('처음 들은 말에서 소라가 필요한 색은 무엇인가요?','파란색','소라가 파란색이 필요하다고 말했다.',[('노란색','민준이 쓰고 있는 색이다.'),('두 색 모두','소라가 두 색 모두 필요하다고 말하지 않았다.')],'색연필을 쓰고 싶어.'),
 O('matching','소라 / 민준의 말을 필요한 색이나 쓰는 색과 이으세요.','소라:파란색 필요 / 민준:노란색 사용',['나는 파란색이 필요해.','나는 노란색을 다 쓰면'],'한 친구의 색만 맞게 이음','두 친구의 색을 바꿈'),
 O('explanation','상대가 대답하는 동안 기다리면 무엇을 알 수 있나요?','그 친구가 실제로 필요한 것을 듣고 내 생각과 같은지 확인할 수 있다.','나는 파란색이 필요해.','기다려야 한다고만 함','기다리지 않아도 친구의 모든 생각을 알 수 있다고 함')])
 E('plan-G1-oral-02','S3','책을 넣고 남은 끈은',[
 ('지안','작은 책을 먼저 넣고 큰 책은 그다음에 넣자.'),('우주','책을 다 넣은 뒤 끈을 정리하자. 끈은 아직 책상 위에 있어.')],
 '여러분도 책 정리를 돕고 있어요. 두 친구가 말한 차례를 듣고, 마지막에 끈을 어디에 둘지 직접 물어보세요. 답을 들은 다음 차례와 놓을 곳을 확인하세요.',
 '끈은 가방 옆 주머니에 넣어 줘.',
 '행동 차례는 들었지만 끈의 보관 장소는 아직 없다. 장소를 알았다고 먼저 말하지 않고 질문 뒤 상대 답에서 확인한다. 말차례를 기다리는 모습과 메모만 작성한 경우를 구별한다.',[
 S('정리할 차례를 짧게 말하고 끈을 둘 곳을 직접 물어보세요. 답을 들은 뒤 다시 확인하세요.','예:작은 책, 큰 책을 넣고 끈을 정리하는 거지? 끈은 어디에 둘까? 답을 들은 뒤 책을 넣은 다음 끈을 옆 주머니에 넣겠다고 확인한다.',['작은 책을 먼저 넣고','책을 다 넣은 뒤 끈을 정리하자.'],[D('두 말 연결','작은 책→큰 책→끈 정리의 흐름을 보존한다.','책 다음 끈만 말하고 두 책의 순서를 놓친다.','끈을 먼저 넣는다고 한다.'),D('필요한 질문·차례','끈을 둘 곳을 묻고 상대가 답할 기회를 준다.','장소 질문이 모호하거나 답을 기다리는 데 도움이 필요하다.','끈의 위치를 정해 놓고 상대 답을 듣지 않는다.'),D('후속 확인','옆 주머니라는 새 답과 정리 차례를 이어 확인한다.','옆 주머니만 되풀이하고 무엇을 넣는지 흐리다.','책상 위에 그대로 두겠다고 상대 답과 다르게 말한다.')]),
 C('처음 들은 안내만으로 아직 모르는 것은 무엇인가요?','끈을 정리해 둘 곳','끈이 지금 책상 위에 있다는 말은 앞으로 보관할 곳의 안내가 아니다.',[('두 책을 넣는 차례','작은 책 다음 큰 책이라고 들었다.'),('끈이 지금 놓인 곳','책상 위라고 들었다.')],'끈은 아직 책상 위에 있어.'),
 O('ordering','작은 책 / 큰 책 / 끈 정리의 차례를 쓰세요.','작은 책 넣기 → 큰 책 넣기 → 끈 정리',['작은 책을 먼저 넣고 큰 책은 그다음에','책을 다 넣은 뒤'],'가운데 한 행동을 빠뜨림','큰 책을 마지막에 넣는다고 함'),
 O('explanation','지금 있는 곳과 정리해 둘 곳을 왜 구별해야 하나요?','책상 위는 현재 위치이고 정리한 뒤 둘 곳은 다른 곳일 수 있어 물어 확인해야 하기 때문이다.','끈은 아직 책상 위에 있어.','다를 수 있다고만 함','현재 위치가 언제나 보관 장소라고 함')])

 E('plan-G2-oral-01','S2','누가 덮개를 닫을까',[
 ('놀이 담당자','다연이가 통의 덮개를 열어요. 은우는 물통을 안에 넣어 주세요.'),('다연','은우가 물통을 넣은 뒤 내가 덮개를 닫을게.')],
 '통을 정리하는 안내를 들으세요. 누가 무엇을 하는지 순서대로 짝에게 알려 주세요. 짝이 다시 물으면 들은 내용으로 확인해 주세요.',
 '그러면 덮개를 닫는 사람도 은우라는 뜻이야?',
 '덮개 열기·닫기와 물통 넣기의 사람을 구별한다. 덮개를 여는 일과 닫는 일은 다연, 물통 넣기는 은우다. 메모 정답과 실제 말하기 관찰을 구별한다.',[
 S('두 사람이 할 일을 차례대로 직접 알려 주세요. 짝의 물음도 듣고 사람과 행동을 확인하세요.','다연이가 덮개를 열고 은우가 물통을 넣은 다음 다연이가 닫는다. 짝이 은우가 닫는지 물으면 닫는 사람은 다연이라고 확인한다.',['다연이가 통의 덮개를 열어요.','은우는 물통을 안에 넣어 주세요.','내가 덮개를 닫을게.'],[D('대상·행동','다연의 열기·닫기와 은우의 넣기를 구별한다.','한 행동의 주체만 맞히거나 닫는 사람을 빠뜨린다.','은우가 열고 다연이 넣는다고 바꾼다.'),D('행동 순서','열기→넣기→닫기의 순서를 보존해 말한다.','행동은 맞지만 차례가 흐리다.','물통을 넣기 전에 닫는다고 한다.'),D('질문 뒤 확인','짝의 잘못된 확인을 듣고 닫는 사람이 다연임을 근거로 다시 말한다.','다연이라고만 말하고 질문과 연결하지 못한다.','짝의 말에 맞추어 닫는 사람을 은우로 바꾼다.')]),
 C('은우가 맡은 일은 무엇인가요?','물통을 통 안에 넣기','담당자가 은우에게 물통을 넣으라고 말했다.',[('통의 덮개를 열기','다연이의 일이다.'),('마지막에 덮개를 닫기','다연이가 하겠다고 말했다.')],'은우는 물통을 안에 넣어 주세요.'),
 O('ordering','덮개 닫기 / 물통 넣기 / 덮개 열기를 들은 순서에 맞게 쓰세요.','다연 덮개 열기 → 은우 물통 넣기 → 다연 덮개 닫기',['다연이가 통의 덮개를','은우가 물통을 넣은 뒤'],'순서는 맞지만 사람 하나를 빠뜨림','닫은 다음 물통을 넣는다고 함'),
 O('evidence_selection','덮개를 닫는 사람을 알아내는 다연의 말을 뜻이 같게 쓰세요.','은우가 넣은 뒤 다연이가 덮개를 닫겠다고 말했다.','은우가 물통을 넣은 뒤 내가 덮개를 닫을게.','닫겠다고만 하고 누구인지 빠뜨림','담당자가 직접 닫는다고 함')])
 E('plan-G2-oral-01','S5','친구가 다르게 전한 안내',[
 ('만들기 담당자','지우는 남은 천을 초록 바구니에 넣고 라온은 종이심을 빨간 상자에 넣어 주세요. 두 가지 모두 다음 놀이에 다시 쓸 거예요.'),('친구','그러면 라온은 종이심을 버리고 지우는 천을 빨간 상자에 넣는 거지?')],
 '담당자의 안내와 친구가 전한 말을 구별해 들으세요. 친구에게 달라진 내용을 바로잡아 말하세요. 친구가 다시 확인하면 왜 그렇게 말했는지도 알려 주세요.',
 '그럼 종이심도 버리지 않고 모아 두는 거야?',
 '말한 사람이 다르다는 이유만으로 판단하지 않고 안내의 실제 대상·행동·장소를 대조한다. 다시 쓰는 두 재료를 구별하고 친구의 확인에 들은 말로 답하게 한다.',[
 S('친구가 다르게 전한 두 내용을 직접 고쳐 알려 주세요. 뒤의 물음에도 들은 안내를 근거로 답하세요.','지우는 천을 초록 바구니에, 라온은 종이심을 빨간 상자에 넣는다. 둘 다 다시 쓰므로 종이심을 버리지 않고 모아 둔다고 확인한다.',['지우는 남은 천을 초록 바구니에','라온은 종이심을 빨간 상자에','두 가지 모두 다음 놀이에 다시 쓸 거예요.'],[D('장소 바로잡기','지우의 천은 초록 바구니라고 고친다.','초록만 말하고 대상이 흐리다.','지우의 천을 빨간 상자에 넣는다고 유지한다.'),D('행동·이유','라온의 종이심은 버리지 않고 빨간 상자에 두며 다시 쓰는 이유를 말한다.','버리지 않는다고만 하고 모을 곳·이유가 빠진다.','라온이 버려야 한다고 한다.'),D('상대 확인에 답하기','종이심도 다시 쓴다는 말을 들어 짝의 확인에 답한다.','맞다고만 대답하고 무엇을 확인한 것인지 흐리다.','상대 답을 듣지 않고 처음 말만 반복한다.')]),
 C('담당자의 안내에 맞는 연결은 무엇인가요?','지우의 천은 초록 바구니에 넣는다.','지우·천·초록 바구니를 함께 연결해야 한다.',[('지우의 천은 빨간 상자에 넣는다.','친구가 잘못 전한 장소이다.'),('라온의 종이심은 버린다.','종이심도 다시 쓸 재료이다.')],'지우는 남은 천을 초록 바구니에'),
 O('matching','천 / 종이심을 사람과 보관할 곳에 각각 이으세요.','천:지우·초록 바구니 / 종이심:라온·빨간 상자',['지우는 남은 천을','라온은 종이심을 빨간 상자에'],'하나의 재료만 맞게 이음','재료와 장소를 바꿈'),
 O('explanation','라온이 종이심을 버리지 않아야 한다고 말할 근거는 무엇인가요?','담당자가 두 가지 모두 다음 놀이에 다시 쓰겠다고 말했다.','두 가지 모두 다음 놀이에 다시 쓸 거예요.','다시 쓴다고만 하고 어떤 재료인지 흐림','친구가 버린다고 말했으므로 버려야 한다고 함'),
 O('revision','지우는 천을 빨간 상자에 넣는 거지라는 말을 들은 안내에 맞게 고치세요.','지우는 남은 천을 초록 바구니에 넣는다.','지우는 남은 천을 초록 바구니에 넣고','색만 바꾸고 재료·사람이 빠짐','지우가 종이심을 버린다고 바꿈')])
